from units import G, FLAP_V, VY_MAX, BIRD_H, FIELD_H


def step_bird(y, vy, flap):
    if flap:
        vy = FLAP_V
    else:
        vy = min(vy + G, VY_MAX)
    y += vy
    alive = True
    if y < 0:
        y = 0
        vy = 0
    elif y + BIRD_H > FIELD_H:
        y = FIELD_H - BIRD_H
        alive = False
    return y, vy, alive

from units import SPAWN_X, SCROLL, PIPE_W, SPAWN_EVERY


def lcg(s):
    return (1103515245 * s + 12345) % 2147483648


def spawn(t, s):
    if t % SPAWN_EVERY != 0:
        return None, s
    s = lcg(s)
    gap_top = 40 + (s >> 8) % 80
    return {"x": SPAWN_X, "gap_top": gap_top, "passed": False}, s


def scroll(pipes):
    for p in pipes:
        p["x"] -= SCROLL


def cull(pipes):
    return [p for p in pipes if p["x"] + PIPE_W > 0]

import physics
import world
import collide
from units import BIRD_X, PIPE_W, GLIDE_VY, Y0


def run(seed, ticks, flaps, powerups=False, trace=None):
    y, vy, score, alive = Y0, 0, 0, True
    s, pipes, ticks_run = seed, [], 0
    for t in range(ticks):
        pipe, s = world.spawn(t, s)
        if pipe is not None:
            pipes.append(pipe)
        y, vy, alive = physics.step_bird(y, vy, flaps[t % len(flaps)] == "1")
        world.scroll(pipes)
        if alive:
            for p in pipes:
                if collide.pipe_hit(y, p):
                    alive = False
                    break
        if alive:
            for p in pipes:
                if not p["passed"] and p["x"] + PIPE_W <= BIRD_X:
                    p["passed"] = True
                    score += 1
                    if abs(vy) <= GLIDE_VY:
                        score += 1
        pipes = world.cull(pipes)
        ticks_run += 1
        if trace is not None:
            trace.append((t, y, vy, score, alive))
        if not alive:
            break
    return {"y": y, "vy": vy, "score": score, "alive": alive,
            "ticks_run": ticks_run}

